// wtest.rs — Zero-arithmetic experiments for idea-generator (provocation wave).
//
// Experiments (each reads data/zeros.txt = 11000 LMFDB ordinates, 34 digits):
//   E1  "zeros are a lattice" : block-start normalization across 20 heights
//       (midpoint-normalized gamma(1+it) phase for zero #N vs zero #N+d).
//   E2  "zeros are separated like primes" : gap statistics — mean/median gaps,
//       close-pair counts (gamma < delta), arithmetic-progression (AP) runs,
//       short-range repulsion exponent via (g_min / mean) scaling with N.
//   E3  "zeros are generated by a polynomial / ODE" : consecutive-difference
//       recurrences (ratio s_n), central-difference derivative estimates.
//   E4  "zeros hide a reflection symmetry" : reflection index delta(i) around
//       the midpoint gamma(N), plus spectral (mod-1) gaps.
//   E5  "zeta is a polynomial" : (2 pi)-fold periods of the Z-function on the
//       Gram lattice (Gram-point counting), computed from block starts.
//   E6  "RH is false" : random-walk / parity signature of Z(t) sign flips
//       relative to a mock off-line pair; also gamma-shifted sign counts.
//
// All output is printed as `E<k> <label> <value>` lines for the note.

use std::f64::consts::PI;
use std::fs;

fn load_ords(path: &str) -> Vec<f64> {
    fs::read_to_string(path)
        .expect("read zeros")
        .lines()
        .filter_map(|l| {
            let l = l.trim();
            if l.is_empty() {
                return None;
            }
            // first token is the index, second is the ordinate
            let mut it = l.split_whitespace();
            let _idx = it.next()?;
            let t: f64 = it.next()?.parse().ok()?;
            Some(t)
        })
        .collect()
}

// theta(t) = Im log Gamma(1/4 + it/2) - (t/2) ln pi, computed with Stirling.
fn theta(t: f64) -> f64 {
    let z = t / 2.0;
    let s = 0.25 + z; // 1/4 + it/2
    let re = 0.25;
    let im = z;
    // log Gamma(1/4 + i z) via Stirling: (s - 1/2) ln s - s + 1/2 ln(2 pi) + 1/(12 s)
    let s_re = re;
    let s_im = im;
    let log_s_re = 0.5 * (s_re * s_re + s_im * s_im).ln();
    let log_s_im = s_im.atan2(s_re);
    let lg_re = (s_re - 0.5) * log_s_re - s_im * log_s_im - s_re + 0.5 * (2.0 * PI).ln()
        + (s_re / (12.0 * (s_re * s_re + s_im * s_im)));
    let lg_im = (s_re - 0.5) * log_s_im + s_im * log_s_re - s_im
        - s_im / (12.0 * (s_re * s_re + s_im * s_im));
    let _ = lg_re;
    lg_im - z * PI.ln()
}

fn main() {
    let ords = load_ords("data/zeros.txt");
    let n = ords.len();
    println!("E0 count {}", n);

    // ---------------- E1: block-start normalization (lattice test) ----------------
    // File data/blocks_orig.txt: "<N_i> <block start t_i>" (1-based zero index at
    // which the block starts). The "lattice" test: theta(b_i)/pi should equal N_i
    // (block starts are Gram-like points). Report mean/sd/max of (theta(b_i)/pi - N_i).
    let block_lines = fs::read_to_string("data/blocks_orig.txt").expect("blocks");
    let mut bstarts: Vec<f64> = Vec::new();
    let mut bids: Vec<f64> = Vec::new();
    for l in block_lines.lines() {
        let mut it = l.split_whitespace();
        if let (Some(m), Some(b)) = (it.next(), it.next()) {
            bids.push(m.parse().unwrap());
            bstarts.push(b.parse().unwrap());
        }
    }
    let mut sum = 0.0f64;
    let mut sum2 = 0.0f64;
    let mut cnt = 0usize;
    let mut max_dev = 0.0f64;
    for (&m, &b) in bids.iter().zip(bstarts.iter()) {
        let t_theta = theta(b) / PI;
        let dev = t_theta - m;
        sum += dev;
        sum2 += dev * dev;
        cnt += 1;
        if dev.abs() > max_dev {
            max_dev = dev.abs();
        }
    }
    let mean = sum / cnt as f64;
    let sd = (sum2 / cnt as f64 - mean * mean).sqrt();
    println!("E1 blocks {} mean_dev {:.5} sd {:.5} max {:.5}", cnt, mean, sd, max_dev);

    // ---------------- E2: gaps, close pairs, AP runs, repulsion ----------------
    let mut gaps_raw: Vec<f64> = Vec::with_capacity(n - 1);
    for w in ords.windows(2) {
        gaps_raw.push(w[1] - w[0]);
    }
    let mut gaps = gaps_raw.clone();
    gaps.sort_by(|a, b| a.partial_cmp(b).unwrap());
    let mean_gap = gaps.iter().sum::<f64>() / gaps.len() as f64;
    let med = gaps[gaps.len() / 2];
    let min_gap = gaps[0];
    let p10 = gaps[gaps.len() / 10];
    let p90 = gaps[9 * gaps.len() / 10];
    // close pairs with gamma < delta (log-scale gaps: g/mean < delta)
    let mut close = 0usize;
    let mut close_d = 0.0f64; // smallest g/mean
    let mut tiny = 0usize;
    for &g in gaps.iter() {
        let r = g / mean_gap;
        if r < 0.5 {
            close += 1;
            if r < close_d || close_d == 0.0 {
                close_d = r;
            }
        }
        if g < 0.25 {
            tiny += 1;
        }
    }
    // AP runs on the *original* (time-ordered) gap sequence: 3-term AP = three
    // consecutive (in index) gaps equal to within a tolerance. Tol in units of mean gap.
    let tol = 1e-3 * mean_gap;
    let mut ap3 = 0usize;
    for w in gaps_raw.windows(3) {
        if (w[1] - w[0]).abs() < tol && (w[2] - w[1]).abs() < tol {
            ap3 += 1;
        }
    }
    // 4-term APs (strict): four consecutive gaps equal within tol
    let mut ap4 = 0usize;
    for w in gaps_raw.windows(4) {
        if (w[1] - w[0]).abs() < tol
            && (w[2] - w[1]).abs() < tol
            && (w[3] - w[2]).abs() < tol
        {
            ap4 += 1;
        }
    }
    // repulsion exponent: (min gap in a block of size B) / mean as function of B
    let mut b = 100usize;
    let mut min_ratio_b = f64::MAX;
    while b <= n / 2 {
        let mut blk_min = f64::MAX;
        for chunk in gaps.chunks(b) {
            let m = chunk.iter().cloned().fold(f64::MAX, f64::min);
            if m < blk_min {
                blk_min = m;
            }
        }
        let r = blk_min / mean_gap;
        if b == 100 {
            println!("E2 rep_b100 {}", r);
        }
        if b == 500 {
            println!("E2 rep_b500 {}", r);
        }
        min_ratio_b = r;
        b *= 5;
    }
    println!(
        "E2 gaps n {} mean {:.4} med {:.4} min {:.4} p10 {:.4} p90 {:.4} close_lt_half {} close_min_ratio {:.4} tiny_lt_0.25 {} ap3 {} ap4 {}",
        gaps.len(),
        mean_gap,
        med,
        min_gap,
        p10,
        p90,
        close,
        close_d,
        tiny,
        ap3,
        ap4
    );
    println!("E2 rep_last {}", min_ratio_b);

    // ---------------- E3: recurrences / derivative estimates ----------------
    // s_n = (gamma_{n+1} - gamma_n)/(gamma_n - gamma_{n-1}) — 3-point ratios
    let mut s_vals: Vec<f64> = Vec::new();
    for i in 1..n - 1 {
        let a = ords[i] - ords[i - 1];
        let b = ords[i + 1] - ords[i];
        if a > 1e-12 {
            s_vals.push(b / a);
        }
    }
    let s_mean = s_vals.iter().sum::<f64>() / s_vals.len() as f64;
    let mut s_dev = 0.0;
    for &s in s_vals.iter() {
        s_dev += (s - 1.0).abs();
    }
    s_dev /= s_vals.len() as f64;
    println!("E3 ratio_mean {:.5} mad_from_1 {:.5}", s_mean, s_dev);

    // ---------------- E4: reflection symmetry ----------------
    let mid_t = ords[n / 2];
    let mut delta_vals: Vec<f64> = Vec::new();
    let mut delta_1_100 = 0usize;
    for i in 0..n / 2 {
        let j = n - 1 - i;
        let delta = (ords[i] + ords[j]) - 2.0 * mid_t; // reflection index ~ 0 if symmetric
        delta_vals.push(delta.abs());
        if delta.abs() < 1.0 {
            delta_1_100 += 1;
        }
    }
    let d_mean = delta_vals.iter().sum::<f64>() / delta_vals.len() as f64;
    // mod-1 spectral gaps
    let mut frac: Vec<f64> = ords.iter().map(|&t| (t / (2.0 * PI)).fract()).collect();
    frac.sort_by(|a, b| a.partial_cmp(b).unwrap());
    let mut spec_gap: Vec<f64> = Vec::new();
    for w in frac.windows(2) {
        spec_gap.push(w[1] - w[0]);
    }
    let sg_mean = spec_gap.iter().sum::<f64>() / spec_gap.len() as f64;
    println!(
        "E4 reflect_mean_delta {:.4} delta_lt_1 {} spec_gap_mean {:.5}",
        d_mean, delta_1_100, sg_mean
    );

    // ---------------- E5: Gram-point / Z-period structure ----------------
    // Gram points g_n: theta(g_n) = pi n. The block starts ARE Gram-like points
    // (theta(b_i) ~ pi * N_i). Count how many zeros fall in each Gram interval
    // (b_i, b_{i+1}) using the *computed* 10000 ordinates (zeros2.txt) which extend
    // to t ~ 9879 < the first block start 5000?? — no: block starts begin at 5000.
    // Use zeros.txt (11000 LMFDB ordinates, up to t=10726) which covers block starts
    // up to ~ 10^4.
    let ords_e5 = load_ords("data/zeros.txt");
    let mut multi = 0usize;
    for w in bstarts.windows(2) {
        let lo = w[0];
        let hi = w[1];
        let mut c = 0usize;
        for &t in ords_e5.iter() {
            if t > lo && t < hi {
                c += 1;
            }
        }
        if c >= 2 {
            multi += 1;
        }
    }
    println!("E5 gram_multi2 {} total_blocks {}", multi, bstarts.len() - 1);

    // ---------------- E6: sign-flip parity / mock off-line ----------------
    // Z(t) ~ 2 sum_{n<=sqrt(t/2pi)} cos(theta - t ln n)/sqrt(n) — approximate for t ~ 10^5-10^6
    // We can't compute exact Z cheaply here (no zeta eval); instead test the parity
    // heuristic with the *mock* assumption: an off-line pair would produce a "double" sign
    // structure. Report only the mean gap vs a mock two-close-pair world.
    // (E6's real content is in pat4/twowin; here just print the tiny-pair rate.)
    let pair_rate = tiny as f64 / gaps.len() as f64;
    println!("E6 tiny_pair_rate {:.6} min_gap_units {:.4}", pair_rate, min_gap / mean_gap);

    println!("DONE");
}
